{
  "tasks": [
    {
      "task_id": "T01",
      "title": "整体销售概况与基础统计",
      "business_question": "当前数据集的总订单量、总销售额及平均单笔销售额是多少？",
      "priority": "P0",
      "priority_reason": "回答核心需求“探索主要差异和规律”的基础，提供数据全貌。删除后无法评估整体规模或作为其他分析的基准。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01_1",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_orders"
              },
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_sales_amount"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_sales_per_order"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "地区维度销售差异分析",
      "business_question": "不同地区的销售额总和及订单数量分布如何？哪个地区贡献最大？",
      "priority": "P0",
      "priority_reason": "直接响应“主要差异”需求，地区是常见的业务分组维度。删除后无法识别地域性的业绩偏差。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S02_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "sales_by_region"
              },
              {
                "function": "count",
                "field": null,
                "alias": "orders_by_region"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S02_2",
          "operation": "sort",
          "params": {
            "field": "sales_by_region",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "品类维度销售表现分析",
      "business_question": "不同产品品类的销售额及成本情况如何？是否存在高销售额低成本的品类？",
      "priority": "P1",
      "priority_reason": "补充性分析，帮助理解产品结构对销售的影响。删除后仍可回答地区差异，但缺乏对产品维度的洞察，分析质量降低。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S03_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "sales_by_category"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "cost_by_category"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S03_2",
          "operation": "sort",
          "params": {
            "field": "sales_by_category",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T04",
      "title": "时间趋势初步探索（按年）",
      "business_question": "各年份的销售总额是否有明显波动或增长规律？",
      "priority": "P2",
      "priority_reason": "探索式需求中的时间规律部分。由于数据仅3行且未指定具体时间范围，此任务为辅助性观察。删除不影响核心差异（地区/品类）的发现。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S04_1",
          "operation": "derive",
          "params": {
            "function": "extract_year",
            "field": "field_0001",
            "alias": "order_year"
          }
        },
        {
          "step_id": "S04_2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "annual_total_sales"
              }
            ],
            "dimensions": [
              "order_year"
            ]
          }
        },
        {
          "step_id": "S04_3",
          "operation": "sort",
          "params": {
            "field": "order_year",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}

{
  "tasks": [
    {
      "task_id": "T01",
      "title": "2026年华东地区非硬件已完成订单销售额Top3",
      "business_question": "在2026年、华东地区、排除硬件品类且状态为已完成的订单中，按地区汇总销售额总和，并取降序前三名。",
      "priority": "P0",
      "priority_reason": "直接响应用户核心分析目标与所有约束条件（时间、地区、状态、品类排除、指标、排序限制）。删除此任务将无法回答用户问题。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04",
        "C05"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0001",
                "operator": "gte",
                "value": "2026-01-01"
              },
              {
                "field": "field_0001",
                "operator": "lt",
                "value": "2027-01-01"
              },
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "华东"
              },
              {
                "field": "field_0006",
                "operator": "eq",
                "value": "已完成"
              },
              {
                "field": "field_0003",
                "operator": "ne",
                "value": "硬件"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_sales"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "top_n",
          "params": {
            "field": "total_sales",
            "direction": "desc",
            "n": 3
          }
        }
      ]
    }
  ]
}

